// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ITetherToken {
    function transfer(address _to, uint _value) external;
    function transferFrom(address _from, address _to, uint _value) external;
    function balanceOf(address _owner) external view returns (uint);
    function approve(address _spender, uint _value) external;
    function allowance(address _owner, address _spender) external view returns (uint);
}

contract VictimContract {
    // Empty contract to hold USDT
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);
    address constant UNISWAP_V2_ROUTER = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Give attacker some initial USDT
        deal(TARGET, attacker, 1 ether);

        // Create a victim contract
        victim = address(new VictimContract());

        // Give victim contract a lot of USDT
        deal(TARGET, victim, 1000 ether);

        // Make victim approve Uniswap V2 router
        vm.prank(victim);
        ITetherToken(TARGET).approve(UNISWAP_V2_ROUTER, type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance
        uint256 initialBalance = ITetherToken(TARGET).balanceOf(attacker);

        // Impersonate Uniswap V2 router
        vm.prank(UNISWAP_V2_ROUTER);

        // Transfer from victim to attacker
        // We need to call transferFrom on TetherToken contract
        ITetherToken(TARGET).transferFrom(victim, attacker, 500 ether);

        // Verify balance increased
        uint256 finalBalance = ITetherToken(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Balance should increase");

        // Verify ERC20 balance increased
        uint256 erc20FinalBalance = IERC20(TARGET).balanceOf(address(this));
        uint256 erc20InitialBalance = initialBalance; // Use the same initial balance
        assertGt(erc20FinalBalance, erc20InitialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

